import { createServer, type IncomingMessage, type ServerResponse, type Server } from 'node:http';
import { readFile } from 'node:fs/promises';

export interface ResponseItem { status: number; headers: Record<string, string>; body: string; delayMs: number; }
interface EndpointState { responses: ResponseItem[]; next: number; }
interface ConfigState { version: number; endpoints: Map<string, EndpointState>; }

const ADMIN_PREFIX = '/__contractlab/';
const HEALTH_PATH = '/__contractlab/health';
const RELOAD_PATH = '/__contractlab/reload';
const VERSION_HEADER = 'x-contractlab-config-version';
const FORBIDDEN_HEADERS = new Set(['content-length', 'transfer-encoding', 'connection']);
```

Validation function `parseConfig(text: string): Map<string, ResponseItem[]>` — returns map key→responses; throws Error with prefixed location.

```ts
function fail(where: string, msg: string): never { throw new Error(`${where}: ${msg}`); }

export function parseConfig(text: string): Map<string, ResponseItem[]> {
  let doc: unknown;
  try { doc = JSON.parse(text); } catch (e) { throw new Error(`invalid JSON: ${(e as Error).message}`); }
  if (typeof doc !== 'object' || doc === null || Array.isArray(doc)) fail('$', 'expected an object');
  const root = doc as Record<string, unknown>;
  for (const k of Object.keys(root)) if (k !== 'endpoints') fail(`$.${k}`, 'unknown field');
  const eps = root.endpoints;
  if (!Array.isArray(eps)) fail('$.endpoints', 'expected an array');
  const out = new Map<string, ResponseItem[]>();
  eps.forEach((ep, i) => {
    const where = `$.endpoints[${i}]`;
    if (typeof ep !== 'object' || ep === null || Array.isArray(ep)) fail(where, 'expected an object');
    const e = ep as Record<string, unknown>;
    for (const k of Object.keys(e)) if (!['method','path','responses'].includes(k)) fail(`${where}.${k}`, 'unknown field');
    if (e.method !== 'GET' && e.method !== 'POST') fail(`${where}.method`, 'expected "GET" or "POST"');
    if (typeof e.path !== 'string' || !e.path.startsWith('/') || e.path.includes('?') || e.path.includes('#') || e.path.length === 0) fail(`${where}.path`, 'expected an absolute path starting with "/" without query');
    if (e.path.startsWith(ADMIN_PREFIX)) fail(`${where}.path`, `conflicts with reserved admin prefix ${ADMIN_PREFIX}`);
    const key = `${e.method} ${e.path}`;
    if (out.has(key)) fail(where, `duplicate endpoint ${key}`);
    if (!Array.isArray(e.responses) || e.responses.length === 0) fail(`${where}.responses`, 'expected a non-empty array');
    const items = e.responses.map((r, j) => parseItem(r, `${where}.responses[${j}]`));
    out.set(key, items);
  });
  return out;
}
```

