function parseItem(r: unknown, where: string): ResponseItem {
  if (typeof r !== 'object' || r === null || Array.isArray(r)) fail(where, 'expected an object');
  const o = r as Record<string, unknown>;
  for (const k of Object.keys(o)) if (!['status','headers','body','delayMs'].includes(k)) fail(`${where}.${k}`, 'unknown field');
  const status = o.status;
  if (typeof status !== 'number' || !Number.isInteger(status) || status < 200 || status > 599) fail(`${where}.status`, 'expected an integer between 200 and 599');
  if (o.body === undefined) ... require body: if (typeof o.body !== 'string') fail(`${where}.body`, 'expected a string');
  const body = o.body;
  if ((status === 204 || status === 304) && body !== '') fail(`${where}.body`, `status ${status} requires an empty body`);
  let headers: Record<string,string> = {};
  if (o.headers !== undefined) {
    if (typeof o.headers !== 'object' || o.headers === null || Array.isArray(o.headers)) fail(`${where}.headers`, 'expected an object of string values');
    for (const [hn, hv] of Object.entries(o.headers)) {
      if (/[\r\n]/.test(hn) || hn === '') fail(`${where}.headers`, `invalid header name ${JSON.stringify(hn)}`);
      if (FORBIDDEN_HEADERS.has(hn.toLowerCase())) fail(..., `header ${hn} is managed by the server`);
      if (typeof hv !== 'string') fail(`${where}.headers.${hn}`, 'expected a string');
      if (/[\r\n]/.test(hv)) fail(..., 'header value must not contain newlines');
      headers[hn] = hv;
    }
  }
  let delayMs = 0;
  if (o.delayMs !== undefined) {
    if (typeof o.delayMs !== 'number' || !Number.isInteger(o.delayMs) || o.delayMs < 0 || o.delayMs > 60000) fail(`${where}.delayMs`, 'expected an integer between 0 and 60000');
    delayMs = o.delayMs;
  }
  return { status, headers, body, delayMs };
}
