  const idx = ep.next < ep.responses.length ? ep.next : ep.responses.length - 1;
  ep.next += 1;
  const item = ep.responses[idx];
  const version = state.version;
  pending.add(res);
  const timer = setTimeout(() => {
    pending.delete(res); timers.delete(res);
    deliver(res, item, version);
  }, item.delayMs);
  timers.set(res, timer);
  res.on('close', () => { pending.delete(res); const t = timers.get(res); if (t) { clearTimeout(t); timers.delete(res); } });
}
